using System;using System.Runtime.InteropServices;
public static class ViewerNative {
 [StructLayout(LayoutKind.Sequential)]public struct HitPoint{public int X,Y;public HitPoint(int x,int y){X=x;Y=y;}}
 [DllImport("user32.dll")]static extern IntPtr WindowFromPoint(HitPoint p);
 [DllImport("user32.dll")]public static extern bool ShowWindow(IntPtr h,int command);
 public static bool OwnPoint(int pid,int x,int y){uint actual;GetWindowThreadProcessId(WindowFromPoint(new HitPoint(x,y)),out actual);return actual==(uint)pid;}
 public static uint HitPid(int x,int y){uint actual;GetWindowThreadProcessId(WindowFromPoint(new HitPoint(x,y)),out actual);return actual;}
 public static uint WindowPid(IntPtr h){uint actual;GetWindowThreadProcessId(h,out actual);return actual;}
 public delegate bool EnumProc(IntPtr h,IntPtr l);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumProc p,IntPtr l);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint p);
 public static IntPtr[] OwnWindows(int pid){var a=new System.Collections.Generic.List<IntPtr>();EnumWindows((h,l)=>{uint p;GetWindowThreadProcessId(h,out p);if(p==pid)a.Add(h);return true;},IntPtr.Zero);return a.ToArray();}
 [DllImport("user32.dll")]public static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int height,uint f);
 [DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")]public static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]public static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")]public static extern int GetSystemMetrics(int index);
 [DllImport("user32.dll")]public static extern void mouse_event(uint f,uint x,uint y,int d,UIntPtr i);
 [DllImport("user32.dll")]public static extern void keybd_event(byte k,byte s,uint f,UIntPtr i);
 public static void MovePointer(int x,int y){mouse_event(0x8001,(uint)Math.Round(x*65535.0/(GetSystemMetrics(0)-1)),(uint)Math.Round(y*65535.0/(GetSystemMetrics(1)-1)),0,UIntPtr.Zero);}
}
