 Click 'GalleryNext';Await {$null -ne (Find 'GalleryImage121')} 'second gallery page';(Find 'GalleryImage121').GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();Await {(State).workspace.gallery.currentId -eq 121} 'page anchor selected';(Find 'GalleryImage121').SetFocus();Key 0x0D;Await {(Viewer).displayedId -eq 121} 'open page2';Click 'ViewerPrevious';Await {(Viewer).displayedId -eq 120} 'viewer crosses page boundary backward';Click 'ViewerNext';Await {(Viewer).displayedId -eq 121} 'viewer crosses page boundary forward';Check ((Viewer).currentId -eq 121) 'continuous viewer is independent of gallery page';Key 0x1B;Await {-not (Viewer).open} 'Esc returns gallery';Check ((State).workspace.gallery.page -eq 2) 'gallery cursor page retained'
