 $originals=0;foreach($catalog in Get-ChildItem -LiteralPath $taskData -Directory -Filter 'engine-probe-*'){$manifest=Join-Path $catalog.FullName 'synthetic-manifest.json';if(Test-Path -LiteralPath $manifest){foreach($entry in (Get-Content -LiteralPath $manifest -Raw | ConvertFrom-Json).images){Check ((Get-FileHash -LiteralPath (Join-Path $catalog.FullName ('demo-images/'+$entry.name)) -Algorithm SHA256).Hash.ToLowerInvariant() -eq $entry.sha256) 'original unchanged';$originals++}}}
 @{result='passed';startupReadyMs=$startupReadyMs;galleryPageReadyMs=$pageReadyMs;firstThumbnailObservedMs=$firstThumbnailObservedMs;visibleThumbnailsReadyMs=$visibleThumbnailsReadyMs;gallerySnapshot=$gallerySnapshot;material=$materialSnapshot;performanceScope='fresh process and fresh synthetic index; OS cache uncontrolled/warmed by earlier runs; diagnostic XAML capture and UIA polling enabled; first thumbnail observed after page readiness is an upper bound';count=$checks.Count;checks=$checks.ToArray();originals=$originals;selectionToViewerMs=$selectionElapsed;viewerMetrics=$perf.metrics;resources=$resources.ToArray();gpu=$gpu;state=(State)} | ConvertTo-Json -Depth 14 | Set-Content -LiteralPath (Join-Path $taskOutput 'viewer-window-report.json');Write-Output ('VIEWER_WINDOW_PASSED '+$checks.Count)
}catch{($_ | Format-List * -Force | Out-String) | Set-Content -LiteralPath (Join-Path $taskOutput 'exception.txt');$failureSnapshot=State;if($failureSnapshot){$failureSnapshot|ConvertTo-Json -Depth 18|Set-Content -LiteralPath (Join-Path $taskOutput 'failure-state.json')};throw}finally{if($process -and -not $process.HasExited){if($hwnd){[ViewerNative]::SetWindowPos($hwnd,[IntPtr](-2),0,0,0,0,0x13)|Out-Null};$process.CloseMainWindow() | Out-Null;$process.WaitForExit(30000) | Out-Null}}
